import{_ as o,o as t,c as d,ag as c}from"./chunks/framework.CQHDKl0N.js";const h=JSON.parse('{"title":"Types","description":"","frontmatter":{},"headers":[],"relativePath":"packages/client/reference/types.md","filePath":"packages/client/docs/reference/types.md"}'),a={name:"packages/client/reference/types.md"};function r(i,e,s,n,l,p){return t(),d("div",null,[...e[0]||(e[0]=[c('<h1 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h1><p>These are exported from <code>@fbritoferreira/strapi</code>. Generated files augment the empty registry interfaces; you do not construct those.</p><h2 id="clients" tabindex="-1">Clients <a class="header-anchor" href="#clients" aria-label="Permalink to &quot;Clients&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Export</th><th>Role</th></tr></thead><tbody><tr><td><code>Strapi</code></td><td>Root client. <code>collection</code>, <code>single</code>, <code>users</code>, <code>files</code>, <code>auth</code>, <code>route</code>, <code>graphql</code>, <code>query</code>, <code>mutate</code>, <code>setToken</code>.</td></tr><tr><td><code>StrapiClient</code></td><td>One collection. Same methods as <code>CollectionClient</code>.</td></tr><tr><td><code>CollectionClient</code></td><td>CRUD for <code>/api/&lt;uid&gt;</code>, plus <code>publish</code>.</td></tr><tr><td><code>SingleTypeClient</code></td><td><code>find</code>, <code>update</code>, <code>publish</code>, <code>delete</code> for a single type.</td></tr><tr><td><code>AuthClient</code></td><td><code>/api/auth/*</code>.</td></tr><tr><td><code>UsersClient</code></td><td><code>/api/users</code>.</td></tr><tr><td><code>FilesClient</code></td><td><code>/api/upload</code>.</td></tr><tr><td><code>HttpClient</code></td><td>Shared <code>fetch</code> wrapper. <code>request</code> returns <code>[error, body]</code>.</td></tr><tr><td><code>generateConfig</code></td><td>Types a codegen config file. Identity at runtime.</td></tr></tbody></table><h2 id="results" tabindex="-1">Results <a class="header-anchor" href="#results" aria-label="Permalink to &quot;Results&quot;">​</a></h2><p><code>Result&lt;T&gt;</code> is <code>[ServiceError, null, null] | [null, T, StrapiMeta]</code>.</p><p><code>StrapiMeta</code> is <code>{ pagination?: StrapiPagination } | null</code>. Pagination is page-shaped (<code>page</code>, <code>pageSize</code>, <code>pageCount</code>, <code>total</code>) or offset-shaped (<code>start</code>, <code>limit</code>, <code>total</code>).</p><p><code>validationIssues(error)</code> returns <code>{ path, message, name? }[]</code>. <code>isValidationDetails</code> narrows <code>details</code>.</p><h2 id="documents" tabindex="-1">Documents <a class="header-anchor" href="#documents" aria-label="Permalink to &quot;Documents&quot;">​</a></h2><p><code>StrapiDocument</code> is <code>id</code>, <code>documentId</code>, <code>createdAt</code>, <code>updatedAt</code>, <code>publishedAt</code>, and optional <code>locale</code>.</p><p><code>StrapiMedia</code> is an uploaded file. See <a href="./../guide/uploads.html">Uploads</a>. <code>StrapiMediaFormat</code> is one generated size. <code>StrapiUser</code> and <code>StrapiRole</code> are the users-permissions shapes. <code>StrapiBlock</code> is one node of a blocks field (<code>type</code>, optional <code>children</code> and <code>text</code>).</p><p><code>AuthSession</code> is <code>{ jwt, refreshToken?, user }</code>. <code>RegisterResult</code> makes <code>jwt</code> optional. <code>RefreshedSession</code> is <code>{ jwt, refreshToken? }</code>. <code>SentEmailConfirmation</code> is <code>{ email, sent }</code>. <code>LogoutResult</code> is <code>{ ok }</code>.</p><h2 id="registries" tabindex="-1">Registries <a class="header-anchor" href="#registries" aria-label="Permalink to &quot;Registries&quot;">​</a></h2><p>Augment these, usually by importing a generated file:</p><ul><li><code>StrapiContentTypes</code>: collection uid to document</li><li><code>StrapiSingleTypes</code>: single-type uid to document</li><li><code>StrapiRoutes</code>: <code>&quot;METHOD /path&quot;</code> to params, query, body and response</li><li><code>StrapiGraphqlQueries</code> / <code>StrapiGraphqlMutations</code>: root field to args and result</li></ul><p>While a registry is empty, any uid is accepted and falls back to <code>object</code>. Once it has keys, an unknown uid is a compile error unless you pass an explicit type argument.</p><p><code>__populatable</code> and <code>__relations</code> are type-level markers the generator adds. Strapi never returns them, and they are excluded from filters, sorts and write payloads.</p>',17)])])}const m=o(a,[["render",r]]);export{h as __pageData,m as default};
